// Normalise et valide le payload entrant
const body = $input.item.json.body || $input.item.json;

if (!body.email) {
  throw new Error('Email manquant dans le payload du lead');
}

return {
  json: {
    email: body.email.toLowerCase().trim(),
    prenom: body.prenom || body.firstName || '',
    nom: body.nom || body.lastName || '',
    message: body.message || '',
    source: body.source || 'unknown',
    received_at: new Date().toISOString()
  }
};

// Scoring du lead selon critères ICP
const lead = $input.item.json;
let score = 0;
const signaux = [];

// Mots-clés d'intention d'achat dans le message
const keywords = ['budget', 'urgent', 'projet', 'demo', 'démo', 'deadline', 'prix', 'devis'];
const messageLC = (lead.message || '').toLowerCase();
const matchedKeywords = keywords.filter(k => messageLC.includes(k));
if (matchedKeywords.length > 0) {
  score += 20;
  signaux.push('Intention achat: ' + matchedKeywords.join(', '));
}

// Email pro vs personnel
const freeProviders = ['gmail.com', 'hotmail.com', 'yahoo.com', 'outlook.com'];
const domain = lead.email.split('@')[1] || '';
if (freeProviders.includes(domain)) {
  score -= 20;
  signaux.push('Email personnel (non pro)');
} else {
  score += 10;
  signaux.push('Email domaine pro: ' + domain);
}

// Longueur / qualité du message (proxy simple d'engagement)
if ((lead.message || '').length > 80) {
  score += 10;
  signaux.push('Message détaillé');
}

// Source
if (lead.source === 'referral' || lead.source === 'linkedin') {
  score += 15;
  signaux.push('Source qualifiée: ' + lead.source);
}

score = Math.max(0, Math.min(100, score));

let category = 'froid';
if (score >= 70) category = 'chaud';
else if (score >= 40) category = 'tiède';

return {
  json: {
    ...lead,
    score,
    category,
    signaux: signaux.join(' | ')
  }
};
